using Orchestration.API.Engineering.Contracts;
namespace Orchestration.API.Engineering.Intelligence;
public interface IEngineeringIntelligenceInvestigationAssembler{EngineeringIntelligenceInvestigation Assemble(UnifiedProductIntelligence input);}
public sealed class EngineeringIntelligenceInvestigationAssembler: IEngineeringIntelligenceInvestigationAssembler
{
 public EngineeringIntelligenceInvestigation Assemble(UnifiedProductIntelligence input){var now=input.AssembledAt;var temporal=new TemporalContext(null,null,now,null,null,null,FreshnessState.Unknown);var subjectId=EngineeringIntelligenceIdentityFactory.Entity(EngineeringEntityKinds.Part,"unified",input.Identity.IdentityId);var subjectProv=new EngineeringProvenance(null,nameof(UnifiedProductIntelligenceAssembler),input.Identity.IdentityId,null,null,null,null,now,IntelligenceAuthority.BackendDerived);var subject=new EngineeringSubject(subjectId,input.Identity.DisplayName,input.Identity.PreferredProductId,input.Identity.CandidateIds.Order(StringComparer.Ordinal).ToArray(),input.Identity.Confidence,input.Identity.Reasons.Order(StringComparer.Ordinal).ToArray(),subjectProv,temporal);
  var entities=new List<EngineeringIntelligenceEntity>();var relationships=new List<EngineeringIntelligenceRelationship>();var evidence=new List<EngineeringIntelligenceEvidence>();var sources=new List<SourceRepresentation>();
  foreach(var source in input.Sources.OrderBy(x=>x.Source)){var sourceName=source.Source.ToString().ToLowerInvariant();var nativeId=source.Candidate?.NativeId??source.Candidate?.DisplayName??sourceName;var entityId=EngineeringIntelligenceIdentityFactory.Entity(EngineeringEntityKinds.SourceRepresentation,sourceName,nativeId);var status=MapStatus(source.Status);var provider=source.Provenance.Provider;var prov=new EngineeringProvenance(source.Source,provider,nativeId,source.Candidate?.Revision,null,source.Provenance.Reference,null,source.Provenance.ObservedAt,IntelligenceAuthority.SourceAuthoritative);var props=new SortedDictionary<string,IntelligenceProperty>(StringComparer.Ordinal){{"status",new("text",status.ToString())}};entities.Add(new(entityId,EngineeringEntityKinds.SourceRepresentation,source.Candidate?.DisplayName??source.Source.ToString(),IdentityQuality.Native,IntelligenceAssertionKind.Fact,props,prov,temporal));relationships.Add(new(EngineeringIntelligenceIdentityFactory.Relationship(EngineeringRelationshipKinds.RepresentedBy,subjectId,entityId),EngineeringRelationshipKinds.RepresentedBy,EngineeringRelationshipFamilies.Correspondence,subjectId,entityId,IntelligenceAssertionKind.Fact,null,Array.Empty<string>(),new Dictionary<string,IntelligenceProperty>(),prov,temporal));var ids=new List<string>();foreach(var r in source.References.OrderBy(x=>x.EvidenceKind).ThenBy(x=>x.Reference,StringComparer.Ordinal)){var id=EngineeringIntelligenceIdentityFactory.Evidence(r.Source,r.SourceExecutionId,r.EvidenceKind,r.Reference);ids.Add(id);evidence.Add(new(id,r.EvidenceKind,$"{r.Source} {r.EvidenceKind}",r.Source,r.SourceExecutionId,r.Reference,r.Checksum,new Dictionary<string,IntelligenceProperty>(),new(r.Source,provider,nativeId,source.Candidate?.Revision,r.SourceExecutionId,r.Reference,r.Checksum,source.Provenance.ObservedAt,IntelligenceAuthority.SourceAuthoritative),temporal));}sources.Add(new(entityId,source.Source,status,nativeId,source.Candidate?.Revision,source.Candidate?.Version,source.Warnings.Select(x=>x.Code).Order(StringComparer.Ordinal).ToArray(),source.Errors.Select(x=>x.Code).Order(StringComparer.Ordinal).ToArray(),prov));}
  var evByKey=evidence.ToDictionary(x=>$"{x.Source}|{x.SourceExecutionId}|{x.Kind}|{x.Reference}",x=>x.Id,StringComparer.Ordinal);var findings=input.Findings.OrderBy(x=>x.FindingId,StringComparer.Ordinal).Select(f=>{var ev=f.Evidence.Select(x=>evByKey.GetValueOrDefault($"{x.Source}|{x.SourceExecutionId}|{x.EvidenceKind}|{x.Reference}")).Where(x=>x is not null).Cast<string>().Distinct().Order(StringComparer.Ordinal).ToArray();return new EngineeringIntelligenceFinding(EngineeringIntelligenceIdentityFactory.Finding(f.Code,subjectId,f.FindingId),f.Code,f.Title,f.Description,f.Severity,IntelligenceAssertionKind.Finding,f.Confidence,new[]{subjectId},ev,f.Confidence is IntelligenceConfidence.Probable or IntelligenceConfidence.Ambiguous or IntelligenceConfidence.Unresolved?FindingReviewState.NeedsReview:FindingReviewState.NotRequired,new(null,nameof(EngineeringFindingEvaluator),null,null,null,null,null,now,IntelligenceAuthority.BackendDerived),temporal);}).ToArray();var cluster=new IdentityCluster(EngineeringIntelligenceIdentityFactory.Cluster(input.Identity.IdentityId),subjectId,entities.Select(x=>x.Id).Prepend(subjectId).Order(StringComparer.Ordinal).ToArray(),input.Identity.Confidence,input.Identity.Reasons.Order(StringComparer.Ordinal).ToArray(),Array.Empty<string>());var summary=new InvestigationSummary(entities.Count,relationships.Count,evidence.Count,findings.Length,sources.Count(x=>x.Status==SourceExtractionStatus.Available),sources.Count(x=>x.Status==SourceExtractionStatus.Partial),input.Status);var result=new EngineeringIntelligenceInvestigation(EngineeringIntelligenceContractVersions.V1,input.IntelligenceId,subject,entities.OrderBy(x=>x.Id,StringComparer.Ordinal).ToArray(),relationships.OrderBy(x=>x.Id,StringComparer.Ordinal).ToArray(),evidence.OrderBy(x=>x.Id,StringComparer.Ordinal).ToArray(),findings,sources.OrderBy(x=>x.Source).ToArray(),new[]{cluster},temporal,summary);var validation=new EngineeringIntelligenceInvestigationValidator().Validate(result);if(!validation.IsValid)throw new InvalidOperationException(string.Join(",",validation.Errors));return result;}
 static SourceExtractionStatus MapStatus(StandardStatus value)=>value switch{StandardStatus.Success=>SourceExtractionStatus.Available,StandardStatus.PartialSuccess=>SourceExtractionStatus.Partial,StandardStatus.Unavailable=>SourceExtractionStatus.Unavailable,StandardStatus.Cancelled=>SourceExtractionStatus.Cancelled,StandardStatus.TimedOut=>SourceExtractionStatus.TimedOut,StandardStatus.CapabilityLimited=>SourceExtractionStatus.CapabilityLimited,StandardStatus.Failed=>SourceExtractionStatus.Failed,_=>SourceExtractionStatus.NotObserved};
}
